package openai
import (
 "encoding/json"
 "testing"
 "github.com/maximhq/bifrost/core/schemas"
)
func TestFactoryRetainedClassifierResponsesCharacterization(t *testing.T) {
 system,user := "classify complexity", "synthetic input"
 limit,temp := 512,0.0
 chat := &schemas.BifrostChatRequest{Provider:schemas.ModelProvider("vercel-classifier"),Model:"openai/gpt-6-luna",Input:[]schemas.ChatMessage{
 {Role:schemas.ChatMessageRoleSystem,Content:&schemas.ChatMessageContent{ContentStr:&system}},
 {Role:schemas.ChatMessageRoleUser,Content:&schemas.ChatMessageContent{ContentStr:&user}},
 },Params:&schemas.ChatParameters{Temperature:&temp,MaxCompletionTokens:&limit}}
 response := chat.ToResponsesRequest()
 response.Params.Temperature=nil
 wire:=ToOpenAIResponsesRequest(nil,response)
 body,err:=json.Marshal(wire);if err!=nil {t.Fatal(err)}
 var fields map[string]json.RawMessage
 if err=json.Unmarshal(body,&fields);err!=nil {t.Fatal(err)}
 if string(fields["model"])!=`"openai/gpt-6-luna"` || string(fields["max_output_tokens"])!="512" {t.Fatalf("model or cap changed: %s",body)}
 for _,key:=range []string{"temperature","max_tokens","max_completion_tokens","store","background","tools","previous_response_id","service_tier"} {if _,ok:=fields[key];ok {t.Fatalf("unexpected field %s: %s",key,body)}}
 t.Logf("synthetic converter output: %s",body)
}
